105|async function request(url, options) {
106|  const response = await fetch(url, options);
107|  let data;
108|  try {
109|    data = await response.json();
110|  } catch (_error) {
111|    data = {};
112|  }
113|  if (!response.ok || !data.ok) {
114|    const error = new Error(data.error || 'Something went wrong. Please try again.');
115|    error.status = response.status;
116|    error.code = data.code;
117|    throw error;
118|  }
119|  return data;
