132|function formatDeadline(timestamp) {
133|  if (!timestamp) return '';
134|  const value = new Date(timestamp);
135|  if (Number.isNaN(value.getTime())) return '';
136|  return new Intl.DateTimeFormat(undefined, {
137|    weekday: 'short', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit',
138|  }).format(value);
