148|function deadlineRemaining() {
149|  if (!session) return 0;
150|  const deadline = new Date(session.deadline_at || session.expires_at).getTime();
151|  return Number.isFinite(deadline) ? deadline - (Date.now() + serverOffsetMs) : 0;
