154|function countdownText(milliseconds) {
155|  const total = Math.max(0, Math.ceil(milliseconds / 1000));
156|  const days = Math.floor(total / 86400);
157|  const hours = Math.floor((total % 86400) / 3600);
158|  const minutes = Math.floor((total % 3600) / 60);
159|  const seconds = total % 60;
160|  if (days) return `${days}d ${hours}h ${minutes}m left`;
161|  if (hours) return `${hours}h ${String(minutes).padStart(2, '0')}m ${String(seconds).padStart(2, '0')}s left`;
162|  return `${minutes}m ${String(seconds).padStart(2, '0')}s left`;
