165|function renderDeadline() {
166|  if (!session) return;
167|  const exact = formatDeadline(session.deadline_at || session.expires_at);
168|  const passed = session.deadline_passed || deadlineRemaining() <= 0;
169|  if (session.status === 'closed') {
170|    elements.deadlineCard.className = 'deadline-card closed';
171|    elements.deadlineCountdown.textContent = 'Order closed';
172|    elements.deadlineDetail.textContent = exact ? `The cutoff was ${exact}. Submitted drinks are read-only.` : 'Submitted drinks are read-only.';
173|  } else if (passed) {
174|    elements.deadlineCard.className = 'deadline-card closed';
175|    elements.deadlineCountdown.textContent = 'Deadline passed';
176|    elements.deadlineDetail.textContent = 'New drinks and edits are locked. Ask the organizer if you arrived late.';
177|  } else if (session.status === 'locked') {
178|    elements.deadlineCard.className = 'deadline-card paused';
179|    elements.deadlineCountdown.textContent = 'Submissions paused';
180|    elements.deadlineDetail.textContent = `${countdownText(deadlineRemaining())} · cutoff ${exact}`;
181|  } else {
182|    elements.deadlineCard.className = 'deadline-card';
183|    elements.deadlineCountdown.textContent = countdownText(deadlineRemaining());
184|    elements.deadlineDetail.textContent = `Submit by ${exact}. The order locks automatically.`;
185|  }
