242|    const button = node('button', `category-chip${activeCategory === choice.name ? ' active' : ''}`, choice.label);
243|    button.type = 'button';
244|    button.setAttribute('aria-pressed', activeCategory === choice.name ? 'true' : 'false');
245|    button.addEventListener('click', () => {
