255|function renderSurpriseControls() {
256|  const randomizer = window.BobaRandomizer;
257|  const choices = menu && randomizer
258|    ? randomizer.eligibleItems(menu, activeCategory) : [];
259|  elements.surpriseMe.disabled = !choices.length;
260|  if (!menu) {
261|    elements.surpriseHint.textContent = 'Picking an orderable drink and options…';
262|  } else if (!choices.length) {
263|    elements.surpriseHint.textContent = 'Surprise Me is for drinks—choose All or another category.';
264|  } else if (activeCategory) {
265|    elements.surpriseHint.textContent = `A random ${activeCategory} drink with valid options, ready to tweak.`;
