275|function renderDrinkList() {
276|  if (!menu) return;
277|  const query = normalized(elements.search.value);
278|  const words = query.split(' ').filter(Boolean);
279|  const matches = menu.items.filter((item) => {
280|    if (activeCategory && item.category !== activeCategory) return false;
281|    const haystack = normalized(`${item.name} ${item.category} ${item.description}`);
282|    return words.every((word) => haystack.includes(word));
283|  });
284|  const visible = matches.slice(0, MAX_VISIBLE_DRINKS);
285|  elements.drinkList.textContent = '';
286|
287|  if (!visible.length) {
288|    elements.drinkList.append(node('p', 'empty-menu', 'No drinks match that search.'));
289|  }
290|  visible.forEach((item) => {
291|    const button = node('button', 'drink-choice');
292|    button.type = 'button';
293|    button.setAttribute('aria-label', `Choose ${item.name}, ${money(item.price)}`);
294|    const wordsBox = node('span');
295|    wordsBox.append(node('span', 'drink-choice-name', item.name));
296|    wordsBox.append(node('span', 'drink-choice-category', item.category));
297|    button.append(wordsBox, node('span', 'drink-choice-price', money(item.price)));
298|    button.addEventListener('click', () => chooseDrink(item));
299|    elements.drinkList.append(button);
300|  });
301|
302|  elements.menuCount.textContent = plural(matches.length, 'drink');
303|  elements.menuMore.textContent = matches.length > visible.length
304|    ? `Showing ${visible.length}. Search to narrow the menu.` : '';
305|}
