307|function initialSelection(group) {
308|  if (group.multiselect) return [];
309|  const marked = group.options.find((option) => option.is_default);
310|  if (group.required && marked) return marked.label;
311|  if (group.required && group.options.length === 1) return group.options[0].label;
312|  return '';
313|}
