315|function chooseDrink(item, existing, chosenSelections) {
316|  selectedItem = item;
317|  selections = {};
318|  item.option_groups.forEach((group) => {
319|    selections[group.key] = initialSelection(group);
320|  });
321|  if (existing) fillExistingSelections(existing);
322|  if (chosenSelections) selections = chosenSelections;
323|
324|  elements.picker.classList.add('hidden');
325|  elements.editor.classList.remove('hidden');
326|  elements.selectedName.textContent = item.name;
327|  elements.selectedDescription.textContent = item.description || '';
328|  elements.selectedPrice.textContent = money(item.price);
329|  elements.removeDrink.setAttribute('aria-label', `Remove ${item.name}`);
330|  renderModifiers();
331|  updateEstimate();
332|  setFormStatus('', '');
333|  if (editingFavoriteId) elements.formTitle.textContent = 'Edit your usual';
334|  else elements.formTitle.textContent = editingOrderId ? 'Edit your drink' : 'Make it yours';
335|  updateFavoriteSaveControls();
336|}
