338|function surpriseMe() {
339|  if (!menu || !window.BobaRandomizer) return;
340|  const surprise = window.BobaRandomizer.pick(menu, activeCategory);
341|  if (!surprise) {
342|    setFormStatus('No orderable drinks are available in this category.', 'err');
343|    return;
344|  }
345|  chooseDrink(surprise.item, null, surprise.selections);
346|  setFormStatus(`✨ Surprise! We picked ${surprise.item.name}. Tweak anything, re-roll, or add it as-is.`,
347|    'surprise');
348|}
349|
350|function fillExistingSelections(order) {
351|  const remainingToppings = (order.toppings || []).slice();
352|  selectedItem.option_groups.filter((group) => group.axis !== 'toppings').forEach((group) => {
353|    const offered = group.options.map((option) => option.label);
354|    const value = order[group.axis] || '';
355|    selections[group.key] = offered.includes(value) ? value : '';
356|  });
357|  const toppingGroups = selectedItem.option_groups.filter((group) => group.axis === 'toppings');
358|  toppingGroups.filter((group) => !group.multiselect).forEach((group) => {
359|    const offered = group.options.map((option) => option.label);
360|    const matchIndex = remainingToppings.findIndex((name) => offered.includes(name));
361|    selections[group.key] = matchIndex >= 0 ? remainingToppings.splice(matchIndex, 1)[0] : '';
362|  });
363|  toppingGroups.filter((group) => group.multiselect).forEach((group) => {
364|    const offered = group.options.map((option) => option.label);
365|    if (group.multiselect) {
366|      const picked = [];
367|      for (let index = remainingToppings.length - 1; index >= 0; index -= 1) {
368|        if (offered.includes(remainingToppings[index])) {
369|          picked.unshift(remainingToppings[index]);
370|          remainingToppings.splice(index, 1);
371|        }
372|      }
373|      selections[group.key] = picked;
374|    }
375|  });
376|}
377|
378|function optionPriceText(option) {
379|  return Number(option.price || 0) ? `+${money(option.price)}` : '';
380|}
381|
382|function renderModifiers() {
383|  elements.modifiers.textContent = '';
384|  selectedItem.option_groups.forEach((group) => {
385|    const fieldset = node('fieldset', 'modifier-group');
386|    fieldset.dataset.groupKey = group.key;
387|    const legend = node('legend', null, group.name);
388|    if (group.required) {
389|      legend.append(document.createTextNode(' '));
390|      legend.append(node('span', 'required-mark', 'Required'));
391|    }
392|    fieldset.append(legend);
393|
394|    if (group.multiselect) {
395|      const grid = node('div', 'option-grid');
396|      group.options.forEach((option) => {
397|        const label = node('label', 'option-check');
398|        const input = document.createElement('input');
399|        input.type = 'checkbox';
400|        input.value = option.label;
401|        input.checked = (selections[group.key] || []).includes(option.label);
402|        input.addEventListener('change', () => {
403|          const values = Array.from(grid.querySelectorAll('input:checked')).map((control) => control.value);
404|          selections[group.key] = values;
405|          enforceMaximum(group, grid);
406|          clearGroupError(fieldset);
407|          updateEstimate();
408|        });
409|        label.append(input, node('span', 'option-name', option.label));
410|        const price = optionPriceText(option);
411|        if (price) label.append(node('span', 'option-price', price));
412|        grid.append(label);
413|      });
414|      fieldset.append(grid);
415|      enforceMaximum(group, grid);
416|    } else {
417|      const select = node('select', 'modifier-select');
418|      select.setAttribute('aria-label', group.name);
419|      if (group.required) select.required = true;
420|      const blank = document.createElement('option');
421|      blank.value = '';
422|      blank.textContent = group.required ? 'Choose one…' : 'Store default / none';
423|      select.append(blank);
424|      group.options.forEach((option) => {
425|        const choice = document.createElement('option');
426|        choice.value = option.label;
427|        const extra = optionPriceText(option);
428|        choice.textContent = `${option.label}${extra ? ` · ${extra}` : ''}`;
429|        choice.selected = selections[group.key] === option.label;
430|        select.append(choice);
431|      });
432|      select.addEventListener('change', () => {
433|        selections[group.key] = select.value;
434|        clearGroupError(fieldset);
435|        updateEstimate();
436|      });
437|      fieldset.append(select);
438|    }
439|    fieldset.append(node('p', 'group-error'));
440|    elements.modifiers.append(fieldset);
441|  });
442|}
443|
444|function enforceMaximum(group, grid) {
445|  if (!group.max) return;
446|  const checked = grid.querySelectorAll('input:checked').length;
447|  grid.querySelectorAll('input').forEach((control) => {
448|    control.disabled = !control.checked && checked >= group.max;
449|  });
450|}
451|
452|function clearGroupError(fieldset) {
453|  const error = fieldset.querySelector('.group-error');
454|  if (error) error.textContent = '';
455|}
456|
457|function selectedOption(group, label) {
458|  return group.options.find((option) => option.label === label);
459|}
460|
461|function updateEstimate() {
462|  if (!selectedItem) {
463|    elements.total.textContent = '—';
464|    elements.selectedOptions.textContent = '';
465|    return;
466|  }
467|  let price = Number(selectedItem.price || 0);
468|  const summary = [];
469|  selectedItem.option_groups.forEach((group) => {
470|    const values = Array.isArray(selections[group.key])
471|      ? selections[group.key] : [selections[group.key]].filter(Boolean);
472|    if (values.length) summary.push(`${group.name}: ${values.join(', ')}`);
473|    values.forEach((value) => {
474|      const option = selectedOption(group, value);
475|      price += Number((option && option.price) || 0);
476|    });
477|  });
478|  elements.selectedOptions.textContent = summary.length ? summary.join(' · ') : 'Store defaults';
479|  const quantity = Math.max(1, Math.min(20, Number(elements.quantity.value) || 1));
480|  elements.total.textContent = money(price * quantity);
481|}
482|
483|function validateSelections() {
484|  let valid = true;
485|  selectedItem.option_groups.forEach((group) => {
486|    const fieldset = elements.modifiers.querySelector(`[data-group-key="${group.key}"]`);
487|    const error = fieldset && fieldset.querySelector('.group-error');
488|    const values = Array.isArray(selections[group.key])
489|      ? selections[group.key] : [selections[group.key]].filter(Boolean);
490|    const minimum = Math.max(Number(group.min || 0), group.required ? 1 : 0);
491|    if (values.length < minimum) {
492|      if (error) error.textContent = minimum === 1 ? 'Choose one option.' : `Choose at least ${minimum}.`;
493|      valid = false;
494|    } else if (group.max && values.length > group.max) {
495|      if (error) error.textContent = `Choose no more than ${group.max}.`;
496|      valid = false;
497|    } else if (error) {
498|      error.textContent = '';
499|    }
500|  });
