322|  const moduleSize = Math.floor(availableSize / (count + quietModules * 2));
323|  const size = moduleSize * (count + quietModules * 2);
324|  const x = left + Math.floor((availableSize - size) / 2);
325|  const y = top + Math.floor((availableSize - size) / 2);
326|  context.fillStyle = '#ffffff';
327|  context.fillRect(x, y, size, size);
328|  context.fillStyle = '#000000';
329|  for (let row = 0; row < count; row += 1) {
330|    for (let column = 0; column < count; column += 1) {
331|      if (model.isDark(row, column)) {
332|        context.fillRect(
333|          x + (column + quietModules) * moduleSize,
334|          y + (row + quietModules) * moduleSize,
335|          moduleSize,
336|          moduleSize,
337|        );
338|      }
339|    }
340|  }
