343|function centeredLines(context, value, centerX, startY, maxWidth, lineHeight, maxLines) {
344|  const words = String(value || '').split(/\s+/).filter(Boolean);
345|  const lines = [];
346|  words.forEach((word) => {
347|    const current = lines[lines.length - 1] || '';
348|    const candidate = current ? `${current} ${word}` : word;
349|    if (current && context.measureText(candidate).width > maxWidth && lines.length < maxLines) {
350|      lines.push(word);
351|    } else if (!lines.length) {
352|      lines.push(word);
353|    } else {
354|      lines[lines.length - 1] = candidate;
355|    }
356|  });
357|  lines.slice(0, maxLines).forEach((line, index) => {
358|    context.fillText(line, centerX, startY + index * lineHeight, maxWidth);
359|  });
360|  return startY + Math.min(lines.length, maxLines) * lineHeight;
