const FULFILLMENT_STAGES = [
  { key: 'collecting', short: 'Collecting' },
  { key: 'ordered', short: 'Ordered' },
  { key: 'ready', short: 'Ready' },
  { key: 'picked_up', short: 'Picked up' },
  { key: 'distributed', short: 'Handed out' },
];

const FULFILLMENT_HINTS = {
  collecting: 'Add drinks before the cutoff. The organizer finalizes and pays on the store site.',
  ordered: 'The organizer placed the order with the store. Watch here instead of asking for updates.',
  ready: 'The store has the drinks ready. The runner is picking them up.',
  picked_up: 'The runner has the drinks and is bringing them over.',
  distributed: 'Every cup has been handed out. Enjoy!',
};

function fulfillment() {
  const fallback = { status: 'collecting', note: '', updated_at: null };
  const value = (session && session.fulfillment) || fallback;
  return {
    status: FULFILLMENT_STAGES.some((stage) => stage.key === value.status) ? value.status : 'collecting',
    note: value.note || '',
    updated_at: value.updated_at || null,
  };
}

function statusTime(timestamp) {
  const date = new Date(timestamp);
  if (Number.isNaN(date.getTime())) return '';
  return new Intl.DateTimeFormat(undefined, { hour: 'numeric', minute: '2-digit' }).format(date);
}

function renderStatusBoard() {
  if (!session || !elements.statusHeading) return;
  const current = fulfillment();
  const labels = {
    collecting: 'Collecting drinks',
    ordered: 'Ordered — with the store',
    ready: 'Ready for pickup',
    picked_up: 'Picked up — on the way',
    distributed: 'All handed out',
  };
  elements.statusHeading.textContent = current.status === 'collecting' && !session.accepting_orders
    ? 'Drinks are in — waiting on the order'
    : labels[current.status];
  elements.statusSteps.textContent = '';
  const currentIndex = FULFILLMENT_STAGES.findIndex((stage) => stage.key === current.status);
  FULFILLMENT_STAGES.forEach((stage, index) => {
    const step = node('li', `status-step${index < currentIndex ? ' done' : ''}${index === currentIndex ? ' current' : ''}`);
    if (index === currentIndex) step.setAttribute('aria-current', 'step');
    step.append(node('span', 'status-step-dot', String(index + 1)));
    step.append(node('span', 'status-step-label', stage.short));
    elements.statusSteps.append(step);
  });
  if (current.note) {
    elements.statusNote.hidden = false;
    elements.statusNote.textContent = `📋 ${current.note}`;
  } else {
    elements.statusNote.hidden = true;
    elements.statusNote.textContent = '';
  }
  const hint = FULFILLMENT_HINTS[current.status] || '';
  const updated = current.updated_at ? `Updated ${statusTime(current.updated_at)}.` : 'No updates yet.';
  elements.statusSub.textContent = `${hint} ${updated}`;
}

function renderRoom() {
  if (!session) return;"}

