{"find":"function render() {
  renderRoom();
  renderDeadline(true);
  renderOrders();
  renderDrinkTotals();
  renderCosts();
}","path":"app/static/group-order-organizer.js","replace":"/* Shared status board controls (Task 19). The organizer (or the runner
   holding this dashboard) advances the stages; participants see the same
   board read-only on the group link. Checkout happens on the store site,
   so no stage is inferred — every move past "collecting" is a manual tap. */
const FULFILLMENT_STAGES = [
  { key: 'collecting', short: 'Collecting', action: 'Back to collecting' },
  { key: 'ordered', short: 'Ordered', action: 'Mark ordered' },
  { key: 'ready', short: 'Ready', action: 'Mark ready' },
  { key: 'picked_up', short: 'Picked up', action: 'Mark picked up' },
  { key: 'distributed', short: 'Handed out', action: 'Mark handed out' },
];

function fulfillment() {
  const value = (session && session.fulfillment) || {};
  const status = FULFILLMENT_STAGES.some((stage) => stage.key === value.status)
    ? value.status : 'collecting';
  return { status, note: value.note || '', updated_at: value.updated_at || null, history: value.history || [] };
}

function renderFulfillment() {
  if (!session || !elements.fulfillmentSteps) return;
  const current = fulfillment();
  const currentIndex = FULFILLMENT_STAGES.findIndex((stage) => stage.key === current.status);

  elements.fulfillmentSteps.textContent = '';
  FULFILLMENT_STAGES.forEach((stage, index) => {
    const step = node('li', `status-step${index < currentIndex ? ' done' : ''}${index === currentIndex ? ' current' : ''}`);
    if (index === currentIndex) step.setAttribute('aria-current', 'step');
    step.append(node('span', 'status-step-dot', String(index + 1)));
    step.append(node('span', 'status-step-label', stage.short));
    elements.fulfillmentSteps.append(step);
  });

  if (document.activeElement !== elements.fulfillmentNote
      && elements.fulfillmentNote.value !== current.note) {
    elements.fulfillmentNote.value = current.note;
  }

  elements.fulfillmentButtons.textContent = '';
  FULFILLMENT_STAGES.forEach((stage) => {
    const button = node('button',
      `btn ${stage.key === current.status ? 'ghost' : 'primary'} compact fulfillment-button`,
      stage.key === current.status ? 'Current' : stage.action);
    button.type = 'button';
    button.disabled = stage.key === current.status;
    button.setAttribute('aria-label',
      stage.key === current.status ? `${stage.short} (current status)` : `Set status to ${stage.short}`);
    button.addEventListener('click', () => updateFulfillment(stage.key));
    elements.fulfillmentButtons.append(button);
  });

  if (!current.history.length) {
    elements.fulfillmentHistory.textContent = current.updated_at
      ? `Last update ${timeText(current.updated_at)}.`
      : 'No status updates yet.';
  } else {
    const trail = current.history.slice(-3).map((entry) => {
      const stage = FULFILLMENT_STAGES.find((candidate) => candidate.key === entry.status);
      return stage ? stage.short : entry.status;
    }).join(' → ');
    elements.fulfillmentHistory.textContent = `Last updates: ${trail}.`;
  }
}

async function updateFulfillment(status) {
  if (!session) return;
  setStatus(elements.fulfillmentStatus, 'Updating the status board…', 'busy');
  elements.fulfillmentButtons.querySelectorAll('button').forEach((button) => { button.disabled = true; });
  try {
    const data = await request(`${apiBase}/fulfillment`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ fulfillment_status: status, note: elements.fulfillmentNote.value.trim() }),
    });
    applyPublicSession(data.session);
    const stage = FULFILLMENT_STAGES.find((candidate) => candidate.key === status);
    setStatus(elements.fulfillmentStatus,
      `Status board: ${(stage && stage.short) || status}. Participants see it on the group link.`, 'ok');
  } catch (error) {
    setStatus(elements.fulfillmentStatus, error.message, 'err');
    renderFulfillment();
  }
}

function render() {
  renderRoom();
  renderDeadline(true);
  renderFulfillment();
  renderOrders();
  renderDrinkTotals();
  renderCosts();
}"}

